BEGIN;
-- Baixa prevista e classificação são uma única operação: request_id nunca pode
-- ser reutilizado com outro payload e uma movimentação só pode baixar um plano.
CREATE TABLE IF NOT EXISTS public.admin_scheduled_account_reconcile_requests (
 id uuid PRIMARY KEY, plan_id uuid REFERENCES public.admin_cash_flow_plans(id),
 ledger_id uuid REFERENCES public.ledger_asaas(id), bank_transaction_id uuid REFERENCES public.admin_bank_transactions(id),
 actor_id uuid NOT NULL DEFAULT auth.uid(), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 CHECK(num_nonnulls(ledger_id,bank_transaction_id)=1)
);
ALTER TABLE public.admin_scheduled_account_reconcile_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.admin_scheduled_account_reconcile_requests FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.admin_scheduled_account_reconcile_requests TO service_role;
CREATE UNIQUE INDEX IF NOT EXISTS admin_cash_flow_plans_one_settlement_per_ledger ON public.admin_cash_flow_plans(ledger_id) WHERE status='settled' AND ledger_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS admin_cash_flow_plans_one_settlement_per_bank ON public.admin_cash_flow_plans(bank_transaction_id) WHERE status='settled' AND bank_transaction_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public.admin_reconcile_category_allowed(p_id uuid,p_direction text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $fn$
 SELECT EXISTS(SELECT 1 FROM public.admin_financial_categories c WHERE c.id=p_id
  AND c.type=CASE WHEN p_direction='credit' THEN 'income' WHEN p_direction='debit' THEN 'expense' END
  AND coalesce((to_jsonb(c)->>'is_active')::boolean,true) AND coalesce((to_jsonb(c)->>'is_manually_selectable')::boolean,true)
  AND coalesce((to_jsonb(c)->>'affects_result')::boolean,true) AND c.name NOT IN ('sale','first_sale','renewal','upgrade'));
$fn$;
CREATE OR REPLACE FUNCTION public.admin_reconcile_asaas_is_neutral(p_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $fn$
 SELECT EXISTS(SELECT 1 FROM public.admin_realized_asaas_movements m WHERE m.id=p_id AND
  (coalesce(m.raw_payload->>'movement_kind',m.raw_payload->'raw_payload'->>'movement_kind','') IN
    ('anticipation_gross','anticipation_debit','opening_balance','adjustment','internal_transfer')
   OR m.asaas_event_type IN ('OPENING_BALANCE','RECONCILIATION_ADJUSTMENT','RECEIVABLE_ANTICIPATION_GROSS_CREDIT','RECEIVABLE_ANTICIPATION_GROSS_DEBIT','RECEIVABLE_ANTICIPATION_DEBIT')
   OR EXISTS(SELECT 1 FROM public.admin_bank_transfers t WHERE t.active AND (t.debit_ledger_id=m.id OR t.credit_ledger_id=m.id))));
$fn$;

CREATE OR REPLACE FUNCTION public.admin_reconciliation_scheduled_account_candidates(
 p_ledger_id uuid DEFAULT NULL,p_bank_transaction_id uuid DEFAULT NULL,p_search text DEFAULT NULL,p_page integer DEFAULT 1,p_page_size integer DEFAULT 30
) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $fn$
DECLARE d text;a numeric;acct uuid;at_ timestamptz;mid uuid;src text;descr text;classified numeric:=0;cats jsonb:='[]';neutral boolean:=false;reason text;out jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_read_admin_financial(auth.uid()) THEN RAISE EXCEPTION 'permission_denied'; END IF;
 IF num_nonnulls(p_ledger_id,p_bank_transaction_id)<>1 OR p_page IS NULL OR p_page_size IS NULL OR p_page<1 OR p_page_size NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'invalid_reconciliation_candidate_request'; END IF;
 IF p_ledger_id IS NOT NULL THEN
  SELECT id,direction,amount,occurred_at,'asaas',coalesce(raw_payload->>'description',raw_payload->'raw_payload'->>'description',asaas_transaction_id) INTO mid,d,a,at_,src,descr FROM public.admin_realized_asaas_movements WHERE id=p_ledger_id;
  SELECT id INTO acct FROM public.admin_bank_accounts WHERE account_kind='asaas' ORDER BY id LIMIT 1; neutral:=public.admin_reconcile_asaas_is_neutral(p_ledger_id);
  IF to_regclass('public.financial_items') IS NOT NULL THEN EXECUTE $q$SELECT coalesce(sum(f.amount),0),coalesce(jsonb_agg(DISTINCT c.id) FILTER(WHERE c.id IS NOT NULL),'[]'::jsonb) FROM public.financial_items f LEFT JOIN public.admin_financial_categories c ON c.name=f.category WHERE f.ledger_asaas_id=$1$q$ INTO classified,cats USING p_ledger_id;
  ELSE SELECT coalesce(sum(t.amount),0),coalesce(jsonb_agg(DISTINCT c.id) FILTER(WHERE c.id IS NOT NULL),'[]'::jsonb) INTO classified,cats FROM public.ledger_asaas m JOIN public.admin_financial_transactions t ON t.id=m.admin_financial_transaction_id OR t.asaas_transaction_id=m.asaas_transaction_id LEFT JOIN public.admin_financial_categories c ON c.name=t.category WHERE m.id=p_ledger_id; END IF;
 ELSE
  SELECT id,CASE WHEN amount>0 THEN 'credit' ELSE 'debit' END,abs(amount),occurred_at,bank_account_id,'bank',coalesce(description,counterparty) INTO mid,d,a,at_,acct,src,descr FROM public.admin_bank_transactions WHERE id=p_bank_transaction_id;
  neutral:=EXISTS(SELECT 1 FROM public.admin_bank_transfers t WHERE t.active AND (t.debit_bank_transaction_id=p_bank_transaction_id OR t.credit_bank_transaction_id=p_bank_transaction_id));
  SELECT coalesce(sum(x.amount),0),coalesce(jsonb_agg(DISTINCT c.id) FILTER(WHERE c.id IS NOT NULL),'[]'::jsonb) INTO classified,cats FROM public.admin_bank_allocations x LEFT JOIN public.admin_financial_transactions t ON t.id=x.admin_transaction_id LEFT JOIN public.admin_financial_categories c ON c.name=t.category WHERE x.bank_transaction_id=p_bank_transaction_id AND x.active;
 END IF;
 IF mid IS NULL THEN RAISE EXCEPTION 'movement_not_found'; END IF;
 IF neutral THEN reason:='neutral_movement_not_reconcilable'; ELSIF classified>a THEN reason:='classification_exceeds_movement'; ELSIF classified>0 AND classified<a THEN reason:='partial_classification'; ELSIF classified>=a THEN reason:='already_classified'; END IF;
 WITH plans AS (SELECT p.*,c.label category_label,b.name bank_account_name FROM public.admin_cash_flow_plans p LEFT JOIN public.admin_financial_categories c ON c.id=p.category_id LEFT JOIN public.admin_bank_accounts b ON b.id=p.bank_account_id WHERE p.status='pending' AND p.direction=d AND p.amount=a AND (CASE WHEN src='asaas' THEN p.bank_account_id IS NULL OR p.bank_account_id=acct ELSE p.bank_account_id=acct END) AND (nullif(btrim(p_search),'') IS NULL OR p.description ILIKE '%'||btrim(p_search)||'%' OR p.counterparty ILIKE '%'||btrim(p_search)||'%')), settled AS (SELECT p.* FROM public.admin_cash_flow_plans p WHERE (p_ledger_id IS NOT NULL AND p.ledger_id=p_ledger_id) OR (p_bank_transaction_id IS NOT NULL AND p.bank_transaction_id=p_bank_transaction_id))
 SELECT jsonb_build_object('movement',jsonb_build_object('source',src,'id',mid,'direction',d,'amount',a,'occurred_at',at_,'bank_account_id',acct,'bank_account_name',(SELECT name FROM public.admin_bank_accounts WHERE id=acct),'description',descr,'classification',jsonb_build_object('classified_amount',classified,'remaining_amount',greatest(a-classified,0),'category_ids',cats,'can_create',NOT neutral AND classified=0,'can_settle',NOT neutral AND classified IN(0,a),'reason',reason)),'candidates',coalesce((SELECT jsonb_agg(to_jsonb(q) ORDER BY q.match_score DESC,q.due_date) FROM(SELECT id,version,description,counterparty,category_id,category_label,amount,due_date,bank_account_id,bank_account_name,CASE WHEN due_date=(at_ AT TIME ZONE 'America/Sao_Paulo')::date THEN 2 WHEN abs(due_date-(at_ AT TIME ZONE 'America/Sao_Paulo')::date)<=7 THEN 1 ELSE 0 END match_score FROM plans ORDER BY match_score DESC,due_date,id OFFSET(p_page-1)*p_page_size LIMIT p_page_size)q),'[]'),'already_settled',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'description',description,'due_date',due_date,'status',status)) FROM settled),'[]'),'total',(SELECT count(*) FROM plans),'page',p_page,'page_size',p_page_size) INTO out;
 RETURN out;
END;$fn$;

CREATE OR REPLACE FUNCTION public.admin_create_reconciled_transaction(p_request_id uuid,p_ledger_id uuid DEFAULT NULL,p_bank_transaction_id uuid DEFAULT NULL,p_category_id uuid DEFAULT NULL,p_description text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$
DECLARE category_name text;d text;a numeric;at_ timestamptz;descr text;payload jsonb;prev public.admin_scheduled_account_reconcile_requests%ROWTYPE;result jsonb;tx uuid;classified numeric;
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_manage_admin_financial(auth.uid()) THEN RAISE EXCEPTION 'permission_denied'; END IF;
 IF p_request_id IS NULL OR p_category_id IS NULL OR num_nonnulls(p_ledger_id,p_bank_transaction_id)<>1 THEN RAISE EXCEPTION 'invalid_reconcile_request'; END IF;
 payload:=jsonb_build_object('operation','create','ledger_id',p_ledger_id,'bank_transaction_id',p_bank_transaction_id,'category_id',p_category_id,'description',nullif(btrim(p_description),''));
 PERFORM pg_advisory_xact_lock(hashtextextended('admin_reconcile_request:'||p_request_id::text,0)); SELECT * INTO prev FROM public.admin_scheduled_account_reconcile_requests WHERE id=p_request_id FOR UPDATE;
 IF FOUND THEN IF (prev.payload-'result') IS DISTINCT FROM payload THEN RAISE EXCEPTION 'request_conflict'; END IF; RETURN jsonb_set(prev.payload->'result','{already_processed}','true'::jsonb); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('admin_reconcile_movement:'||coalesce(p_ledger_id,p_bank_transaction_id)::text,0));
 SELECT name INTO category_name FROM public.admin_financial_categories WHERE id=p_category_id;
 IF p_ledger_id IS NOT NULL THEN
  SELECT direction,amount,occurred_at,coalesce(raw_payload->>'description',raw_payload->'raw_payload'->>'description',asaas_transaction_id) INTO d,a,at_,descr FROM public.admin_realized_asaas_movements WHERE id=p_ledger_id FOR UPDATE;
  IF d IS NULL THEN RAISE EXCEPTION 'movement_not_settled'; END IF; IF public.admin_reconcile_asaas_is_neutral(p_ledger_id) THEN RAISE EXCEPTION 'neutral_movement_not_reconcilable'; END IF;
  IF NOT public.admin_reconcile_category_allowed(p_category_id,d) THEN RAISE EXCEPTION 'invalid_category'; END IF;
  IF to_regclass('public.financial_items') IS NOT NULL THEN EXECUTE 'SELECT coalesce(sum(amount),0) FROM public.financial_items WHERE ledger_asaas_id=$1' INTO classified USING p_ledger_id; IF classified<>0 THEN RAISE EXCEPTION 'existing_classification_conflict'; END IF; SELECT public.admin_classify_asaas_movement(p_ledger_id,p_request_id,jsonb_build_array(jsonb_build_object('category',category_name,'amount',a,'description',coalesce(nullif(btrim(p_description),''),descr)))) INTO result;
  ELSE IF EXISTS(SELECT 1 FROM public.ledger_asaas l JOIN public.admin_financial_transactions t ON t.id=l.admin_financial_transaction_id OR t.asaas_transaction_id=l.asaas_transaction_id WHERE l.id=p_ledger_id) THEN RAISE EXCEPTION 'existing_classification_conflict'; END IF; INSERT INTO public.admin_financial_transactions(type,category,amount,transaction_date,description,asaas_transaction_id,reference_type,created_by) SELECT CASE WHEN d='credit' THEN 'income' ELSE 'expense' END,category_name,a,at_,coalesce(nullif(btrim(p_description),''),descr),asaas_transaction_id,'asaas_reconciliation',auth.uid() FROM public.ledger_asaas WHERE id=p_ledger_id RETURNING id INTO tx; UPDATE public.ledger_asaas SET category=category_name,status='manually_categorized',admin_financial_transaction_id=tx,updated_at=now() WHERE id=p_ledger_id; END IF;
 ELSE
  SELECT CASE WHEN amount>0 THEN 'credit' ELSE 'debit' END,abs(amount),occurred_at,coalesce(description,counterparty) INTO d,a,at_,descr FROM public.admin_bank_transactions WHERE id=p_bank_transaction_id FOR UPDATE; IF d IS NULL THEN RAISE EXCEPTION 'movement_not_found'; END IF; IF NOT public.admin_reconcile_category_allowed(p_category_id,d) THEN RAISE EXCEPTION 'invalid_category'; END IF; SELECT coalesce(sum(amount),0) INTO classified FROM public.admin_bank_allocations WHERE bank_transaction_id=p_bank_transaction_id AND active; IF classified<>0 THEN RAISE EXCEPTION 'existing_classification_conflict'; END IF; PERFORM public.admin_reconcile_bank_transaction(p_request_id,p_bank_transaction_id,jsonb_build_array(jsonb_build_object('category',category_name,'amount',a,'description',coalesce(nullif(btrim(p_description),''),descr))));
 END IF;
 result:=jsonb_build_object('source',CASE WHEN p_ledger_id IS NULL THEN 'bank' ELSE 'asaas' END,'id',coalesce(p_ledger_id,p_bank_transaction_id),'category_id',p_category_id,'created',true,'already_processed',false);
 INSERT INTO public.admin_scheduled_account_reconcile_requests(id,ledger_id,bank_transaction_id,actor_id,payload) VALUES(p_request_id,p_ledger_id,p_bank_transaction_id,auth.uid(),payload||jsonb_build_object('result',result)); RETURN result;
END;$fn$;

CREATE OR REPLACE FUNCTION public.admin_reconcile_scheduled_account(p_request_id uuid,p_plan_id uuid,p_expected_version integer,p_ledger_id uuid DEFAULT NULL,p_bank_transaction_id uuid DEFAULT NULL,p_category_id uuid DEFAULT NULL,p_description text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$
DECLARE p public.admin_cash_flow_plans%ROWTYPE;d text;a numeric;acct uuid;cat uuid;classified numeric:=0;cats jsonb:='[]';payload jsonb;prev public.admin_scheduled_account_reconcile_requests%ROWTYPE;created jsonb;changed public.admin_cash_flow_plans%ROWTYPE;result jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_manage_admin_financial(auth.uid()) THEN RAISE EXCEPTION 'permission_denied'; END IF;
 IF p_request_id IS NULL OR p_plan_id IS NULL OR p_expected_version IS NULL OR num_nonnulls(p_ledger_id,p_bank_transaction_id)<>1 THEN RAISE EXCEPTION 'invalid_reconcile_request'; END IF;
 payload:=jsonb_build_object('operation','settle','plan_id',p_plan_id,'expected_version',p_expected_version,'ledger_id',p_ledger_id,'bank_transaction_id',p_bank_transaction_id,'category_id',p_category_id,'description',nullif(btrim(p_description),''));
 PERFORM pg_advisory_xact_lock(hashtextextended('admin_reconcile_request:'||p_request_id::text,0)); SELECT * INTO prev FROM public.admin_scheduled_account_reconcile_requests WHERE id=p_request_id FOR UPDATE; IF FOUND THEN IF(prev.payload-'result') IS DISTINCT FROM payload THEN RAISE EXCEPTION 'request_conflict'; END IF; RETURN jsonb_set(prev.payload->'result','{already_processed}','true'::jsonb); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('admin_reconcile_movement:'||coalesce(p_ledger_id,p_bank_transaction_id)::text,0)); SELECT * INTO p FROM public.admin_cash_flow_plans WHERE id=p_plan_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'scheduled_account_not_found'; END IF; IF p.version IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'stale_scheduled_account'; END IF; IF p.status<>'pending' THEN RAISE EXCEPTION 'scheduled_account_not_open'; END IF;
 IF p_ledger_id IS NOT NULL THEN SELECT direction,amount,(SELECT id FROM public.admin_bank_accounts WHERE account_kind='asaas' ORDER BY id LIMIT 1) INTO d,a,acct FROM public.admin_realized_asaas_movements WHERE id=p_ledger_id FOR UPDATE; IF d IS NULL THEN RAISE EXCEPTION 'movement_not_found'; END IF; IF public.admin_reconcile_asaas_is_neutral(p_ledger_id) THEN RAISE EXCEPTION 'neutral_movement_not_reconcilable'; END IF; IF to_regclass('public.financial_items') IS NOT NULL THEN EXECUTE $q$SELECT coalesce(sum(f.amount),0),coalesce(jsonb_agg(DISTINCT c.id) FILTER(WHERE c.id IS NOT NULL),'[]'::jsonb) FROM public.financial_items f LEFT JOIN public.admin_financial_categories c ON c.name=f.category WHERE f.ledger_asaas_id=$1$q$ INTO classified,cats USING p_ledger_id; ELSE SELECT coalesce(sum(t.amount),0),coalesce(jsonb_agg(DISTINCT c.id) FILTER(WHERE c.id IS NOT NULL),'[]'::jsonb) INTO classified,cats FROM public.ledger_asaas m JOIN public.admin_financial_transactions t ON t.id=m.admin_financial_transaction_id OR t.asaas_transaction_id=m.asaas_transaction_id LEFT JOIN public.admin_financial_categories c ON c.name=t.category WHERE m.id=p_ledger_id; END IF;
 ELSE SELECT CASE WHEN amount>0 THEN 'credit' ELSE 'debit' END,abs(amount),bank_account_id INTO d,a,acct FROM public.admin_bank_transactions WHERE id=p_bank_transaction_id FOR UPDATE; IF d IS NULL THEN RAISE EXCEPTION 'movement_not_found'; END IF; IF EXISTS(SELECT 1 FROM public.admin_bank_transfers t WHERE t.active AND(t.debit_bank_transaction_id=p_bank_transaction_id OR t.credit_bank_transaction_id=p_bank_transaction_id)) THEN RAISE EXCEPTION 'neutral_movement_not_reconcilable'; END IF; SELECT coalesce(sum(x.amount),0),coalesce(jsonb_agg(DISTINCT c.id) FILTER(WHERE c.id IS NOT NULL),'[]'::jsonb) INTO classified,cats FROM public.admin_bank_allocations x LEFT JOIN public.admin_financial_transactions t ON t.id=x.admin_transaction_id LEFT JOIN public.admin_financial_categories c ON c.name=t.category WHERE x.bank_transaction_id=p_bank_transaction_id AND x.active; END IF;
 IF p.direction<>d OR p.amount<>a OR (p_ledger_id IS NOT NULL AND p.bank_account_id IS NOT NULL AND p.bank_account_id<>acct) OR(p_bank_transaction_id IS NOT NULL AND p.bank_account_id IS DISTINCT FROM acct) THEN RAISE EXCEPTION 'scheduled_account_movement_mismatch'; END IF;
 cat:=coalesce(p_category_id,p.category_id,CASE WHEN classified=a AND jsonb_array_length(cats)=1 THEN (cats->>0)::uuid END); IF cat IS NULL OR NOT public.admin_reconcile_category_allowed(cat,d) THEN RAISE EXCEPTION 'invalid_category'; END IF;
 IF classified=0 THEN created:=public.admin_create_reconciled_transaction(gen_random_uuid(),p_ledger_id,p_bank_transaction_id,cat,p_description); ELSIF classified=a AND cats=jsonb_build_array(cat) THEN created:=jsonb_build_object('created',false); ELSE RAISE EXCEPTION 'existing_classification_conflict'; END IF;
 UPDATE public.admin_cash_flow_plans SET status='settled',ledger_id=p_ledger_id,bank_transaction_id=p_bank_transaction_id,category_id=cat,settled_at=now() WHERE id=p.id RETURNING * INTO changed;
 result:=jsonb_build_object('plan_id',changed.id,'status',changed.status,'version',changed.version,'category_id',cat,'created',coalesce((created->>'created')::boolean,false),'already_processed',false);
 INSERT INTO public.admin_scheduled_account_reconcile_requests(id,plan_id,ledger_id,bank_transaction_id,actor_id,payload) VALUES(p_request_id,p.id,p_ledger_id,p_bank_transaction_id,auth.uid(),payload||jsonb_build_object('result',result)); RETURN result;
END;$fn$;

CREATE OR REPLACE FUNCTION public.admin_block_unreconcile_settled_plan() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $fn$
BEGIN IF (TG_OP='DELETE' OR(OLD.active AND NOT NEW.active)) AND EXISTS(SELECT 1 FROM public.admin_cash_flow_plans p WHERE p.bank_transaction_id=OLD.bank_transaction_id AND p.status='settled') THEN RAISE EXCEPTION 'unreconcile_requires_unsettling_scheduled_account'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END;$fn$;
DROP TRIGGER IF EXISTS admin_block_unreconcile_settled_plan ON public.admin_bank_allocations;
CREATE TRIGGER admin_block_unreconcile_settled_plan BEFORE UPDATE OR DELETE ON public.admin_bank_allocations FOR EACH ROW EXECUTE FUNCTION public.admin_block_unreconcile_settled_plan();
DO $do$ BEGIN IF to_regclass('public.financial_items') IS NOT NULL THEN EXECUTE $sql$CREATE OR REPLACE FUNCTION public.admin_block_unclassify_settled_asaas() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $fn$ BEGIN IF (TG_OP='DELETE' OR NEW.ledger_asaas_id IS DISTINCT FROM OLD.ledger_asaas_id OR NEW.amount IS DISTINCT FROM OLD.amount OR NEW.category IS DISTINCT FROM OLD.category) AND EXISTS(SELECT 1 FROM public.admin_cash_flow_plans p WHERE p.ledger_id=OLD.ledger_asaas_id AND p.status='settled') THEN RAISE EXCEPTION 'unreconcile_requires_unsettling_scheduled_account'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END;$fn$$sql$; EXECUTE 'DROP TRIGGER IF EXISTS admin_block_unclassify_settled_asaas ON public.financial_items'; EXECUTE 'CREATE TRIGGER admin_block_unclassify_settled_asaas BEFORE DELETE OR UPDATE OF ledger_asaas_id,amount,category ON public.financial_items FOR EACH ROW EXECUTE FUNCTION public.admin_block_unclassify_settled_asaas()'; ELSIF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='ledger_asaas' AND column_name='admin_financial_transaction_id') THEN EXECUTE $sql$CREATE OR REPLACE FUNCTION public.admin_block_unclassify_settled_asaas() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $fn$ BEGIN IF (NEW.admin_financial_transaction_id IS DISTINCT FROM OLD.admin_financial_transaction_id OR NEW.category IS DISTINCT FROM OLD.category OR NEW.amount IS DISTINCT FROM OLD.amount OR NEW.direction IS DISTINCT FROM OLD.direction) AND EXISTS(SELECT 1 FROM public.admin_cash_flow_plans p WHERE p.ledger_id=OLD.id AND p.status='settled') THEN RAISE EXCEPTION 'unreconcile_requires_unsettling_scheduled_account'; END IF; RETURN NEW; END;$fn$$sql$; EXECUTE 'DROP TRIGGER IF EXISTS admin_block_unclassify_settled_asaas ON public.ledger_asaas'; EXECUTE 'CREATE TRIGGER admin_block_unclassify_settled_asaas BEFORE UPDATE OF admin_financial_transaction_id,category,amount,direction ON public.ledger_asaas FOR EACH ROW EXECUTE FUNCTION public.admin_block_unclassify_settled_asaas()'; END IF; END$do$;
REVOKE ALL ON FUNCTION public.admin_reconcile_category_allowed(uuid,text),public.admin_reconcile_asaas_is_neutral(uuid),public.admin_reconciliation_scheduled_account_candidates(uuid,uuid,text,integer,integer),public.admin_create_reconciled_transaction(uuid,uuid,uuid,uuid,text),public.admin_reconcile_scheduled_account(uuid,uuid,integer,uuid,uuid,uuid,text),public.admin_block_unreconcile_settled_plan(),public.admin_block_unclassify_settled_asaas() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.admin_reconciliation_scheduled_account_candidates(uuid,uuid,text,integer,integer),public.admin_create_reconciled_transaction(uuid,uuid,uuid,uuid,text),public.admin_reconcile_scheduled_account(uuid,uuid,integer,uuid,uuid,uuid,text) TO authenticated;
COMMIT;
